"""Fixed, progressively enriched medication questions; no artificial repeated joins."""
WORKLOADS={
'L1_candidates':{
 'question':'Which source witnesses reach a frozen tariff?',
 'SQL':"""SELECT w.id witness,p.id product,c.id code,t.id tariff_record FROM witness w JOIN product p ON p.id=w.product JOIN concept c ON c.id=w.code JOIN tariff t ON t.code=c.id WHERE w.jurisdiction='CH' AND w.rule IN ('direct_SAI','via_authorization_SL')""",
 'Cypher':"""MATCH (w:Association)-[:ABOUT_PRODUCT]->(p:ProductRef),(w)-[:TARGET_ATC]->(c:ATCConcept),(t:SourceRecord {file:'ze_definitions.csv'}) WHERE w.jurisdiction='CH' AND w.rule IN ['direct_SAI','via_authorization_SL'] AND t.tariff_atc=c.id RETURN w.id AS witness,p.id AS product,c.id AS code,t.id AS tariff_record"""},
'L2_source_lineage':{
 'question':'Which exact premise and snapshot explain each tariff connection?',
 'SQL':"""SELECT w.id witness,p.id product,c.id code,t.id tariff_record,r.id premise,f.id source_snapshot FROM witness w JOIN product p ON p.id=w.product JOIN concept c ON c.id=w.code JOIN tariff t ON t.code=c.id JOIN premise link ON link.witness=w.id JOIN record r ON r.id=link.record JOIN snapshot f ON f.id=r.snapshot WHERE w.jurisdiction='CH' AND w.rule IN ('direct_SAI','via_authorization_SL')""",
 'Cypher':"""MATCH (w:Association)-[:ABOUT_PRODUCT]->(p:ProductRef),(w)-[:TARGET_ATC]->(c:ATCConcept),(t:SourceRecord {file:'ze_definitions.csv'}),(w)-[:SUPPORTED_BY]->(r:SourceRecord)-[:IN_SNAPSHOT]->(f:SourceSnapshot) WHERE w.jurisdiction='CH' AND w.rule IN ['direct_SAI','via_authorization_SL'] AND t.tariff_atc=c.id RETURN w.id AS witness,p.id AS product,c.id AS code,t.id AS tariff_record,r.id AS premise,f.id AS source_snapshot"""},
'L3_rule_dictionary':{
 'question':'Which rule implementation, dictionary snapshot and tariff snapshot bind the explanation?',
 'SQL':"""SELECT w.id witness,p.id product,c.id code,t.id tariff_record,r.id premise,f.id source_snapshot,g.id derivation_rule,g.implementation implementation,d.id dictionary_snapshot,tf.id tariff_snapshot FROM witness w JOIN product p ON p.id=w.product JOIN concept c ON c.id=w.code JOIN tariff t ON t.code=c.id JOIN premise link ON link.witness=w.id JOIN record r ON r.id=link.record JOIN snapshot f ON f.id=r.snapshot JOIN rule g ON g.id=w.rule_id JOIN snapshot d ON d.id=w.dictionary_snapshot JOIN record tr ON tr.id=t.id JOIN snapshot tf ON tf.id=tr.snapshot WHERE w.jurisdiction='CH' AND w.rule IN ('direct_SAI','via_authorization_SL')""",
 'Cypher':"""MATCH (w:Association)-[:ABOUT_PRODUCT]->(p:ProductRef),(w)-[:TARGET_ATC]->(c:ATCConcept),(t:SourceRecord {file:'ze_definitions.csv'})-[:IN_SNAPSHOT]->(tf:SourceSnapshot),(w)-[:SUPPORTED_BY]->(r:SourceRecord)-[:IN_SNAPSHOT]->(f:SourceSnapshot),(w)-[:GENERATED_BY]->(g:Rule),(w)-[:CHECKED_AGAINST]->(d:SourceSnapshot) WHERE w.jurisdiction='CH' AND w.rule IN ['direct_SAI','via_authorization_SL'] AND t.tariff_atc=c.id RETURN w.id AS witness,p.id AS product,c.id AS code,t.id AS tariff_record,r.id AS premise,f.id AS source_snapshot,g.id AS derivation_rule,g.implementation_sha256 AS implementation,d.id AS dictionary_snapshot,tf.id AS tariff_snapshot"""},
'L4_cross_source_context':{
 'question':'How do direct and package-derived classifications meet at one authorization, with both source lineages and tariff context?',
 'SQL':"""SELECT a.id direct_witness,b.id package_witness,p.id product,ca.id direct_code,cb.id package_code,t.id tariff_record,s.id authorization_record,l.id package_record,sf.id authorization_snapshot,lf.id package_snapshot,ga.id direct_rule,gb.id package_rule,da.id direct_dictionary,db.id package_dictionary FROM witness a JOIN product p ON p.id=a.product JOIN witness b ON b.product=p.id JOIN concept ca ON ca.id=a.code JOIN concept cb ON cb.id=b.code JOIN tariff t ON t.code=cb.id JOIN premise ap ON ap.witness=a.id JOIN record s ON s.id=ap.record AND s.file='sai_praeparate.csv' JOIN premise bp ON bp.witness=b.id AND bp.record=s.id JOIN premise bl ON bl.witness=b.id JOIN record l ON l.id=bl.record AND l.file='sl.csv' JOIN snapshot sf ON sf.id=s.snapshot JOIN snapshot lf ON lf.id=l.snapshot JOIN rule ga ON ga.id=a.rule_id JOIN rule gb ON gb.id=b.rule_id JOIN snapshot da ON da.id=a.dictionary_snapshot JOIN snapshot db ON db.id=b.dictionary_snapshot WHERE a.jurisdiction='CH' AND b.jurisdiction='CH' AND a.rule='direct_SAI' AND b.rule='via_authorization_SL'""",
 'Cypher':"""MATCH (a:Association)-[:ABOUT_PRODUCT]->(p:ProductRef)<-[:ABOUT_PRODUCT]-(b:Association),(a)-[:TARGET_ATC]->(ca:ATCConcept),(b)-[:TARGET_ATC]->(cb:ATCConcept),(t:SourceRecord {file:'ze_definitions.csv'}),(a)-[:SUPPORTED_BY]->(s:SourceRecord {file:'sai_praeparate.csv'})<-[:SUPPORTED_BY]-(b),(b)-[:SUPPORTED_BY]->(l:SourceRecord {file:'sl.csv'}),(s)-[:IN_SNAPSHOT]->(sf:SourceSnapshot),(l)-[:IN_SNAPSHOT]->(lf:SourceSnapshot),(a)-[:GENERATED_BY]->(ga:Rule),(b)-[:GENERATED_BY]->(gb:Rule),(a)-[:CHECKED_AGAINST]->(da:SourceSnapshot),(b)-[:CHECKED_AGAINST]->(db:SourceSnapshot) WHERE a.jurisdiction='CH' AND b.jurisdiction='CH' AND a.rule='direct_SAI' AND b.rule='via_authorization_SL' AND t.tariff_atc=cb.id RETURN a.id AS direct_witness,b.id AS package_witness,p.id AS product,ca.id AS direct_code,cb.id AS package_code,t.id AS tariff_record,s.id AS authorization_record,l.id AS package_record,sf.id AS authorization_snapshot,lf.id AS package_snapshot,ga.id AS direct_rule,gb.id AS package_rule,da.id AS direct_dictionary,db.id AS package_dictionary"""},
'L5_peer_indication_evidence':{
 'question':'For each candidate, how many distinct other same-tariff authorizations and indication premises are reachable?',
 'SQL':"""SELECT sp.id product,t.id tariff_record,count(DISTINCT pp.id) peer_count,count(DISTINCT i.id) indication_witnesses,count(DISTINCT r.id) source_records,count(DISTINCT g.id) derivation_rules FROM witness src JOIN product sp ON sp.id=src.product JOIN concept c ON c.id=src.code JOIN tariff t ON t.code=c.id JOIN witness peer ON peer.code=c.id JOIN product pp ON pp.id=peer.product AND pp.id<>sp.id JOIN indication i ON i.product=pp.id JOIN record r ON r.id=i.record JOIN snapshot f ON f.id=r.snapshot JOIN rule g ON g.id=peer.rule_id JOIN snapshot d ON d.id=peer.dictionary_snapshot WHERE src.jurisdiction='CH' AND peer.jurisdiction='CH' AND src.rule IN ('direct_SAI','via_authorization_SL') AND peer.rule IN ('direct_SAI','via_authorization_SL') GROUP BY sp.id,t.id""",
 'Cypher':"""MATCH (src:Association)-[:ABOUT_PRODUCT]->(sp:ProductRef),(src)-[:TARGET_ATC]->(c:ATCConcept)<-[:TARGET_ATC]-(peer:Association)-[:ABOUT_PRODUCT]->(pp:ProductRef),(t:SourceRecord {file:'ze_definitions.csv'}),(i:IndicationAssertion)-[:ABOUT_PRODUCT]->(pp),(i)-[:SUPPORTED_BY]->(r:SourceRecord)-[:IN_SNAPSHOT]->(f:SourceSnapshot),(peer)-[:GENERATED_BY]->(g:Rule),(peer)-[:CHECKED_AGAINST]->(d:SourceSnapshot) WHERE src.jurisdiction='CH' AND peer.jurisdiction='CH' AND src.rule IN ['direct_SAI','via_authorization_SL'] AND peer.rule IN ['direct_SAI','via_authorization_SL'] AND sp<>pp AND t.tariff_atc=c.id RETURN sp.id AS product,t.id AS tariff_record,count(DISTINCT pp.id) AS peer_count,count(DISTINCT i.id) AS indication_witnesses,count(DISTINCT r.id) AS source_records,count(DISTINCT g.id) AS derivation_rules"""}}
